  "matrices-and-vectors.mu.check": "<div class='ck'>Comprueba la última entrada: fila {m} de {a} por columna {p} de {b} = {e}{ok}</div>",
  "matrices-and-vectors.mu.rowTimesCol": "<div class='ck'>Multiplicar es <b>fila por columna</b> — no entrada por entrada, y no en cualquier orden: por lo general {ab} ≠ {ba}.</div>",

  // ---- determinant ----
  "matrices-and-vectors.det.byRows": " <span class=\"nm\">(por reducción de filas)</span>",
  "matrices-and-vectors.det.start": "<span class='lead'>La matriz:</span> {a} es de {n} × {n} (cuadrada), así que tiene determinante, que se escribe {dh} o |{a}|.",
  "matrices-and-vectors.det.sarrusNo2": " (La regla de Sarrus solo funciona para 3 × 3, así que aquí se usa ad − bc.)",
  "matrices-and-vectors.det.sarrusNoRows": " (La regla de Sarrus solo funciona para 3 × 3, así que aquí se usa reducción de filas.)",
  "matrices-and-vectors.det.startSay": "Una matriz de {n} × {n} tiene un determinante: un solo número.",
  "matrices-and-vectors.det.formula": "<span class='lead'>Para una de 2 × 2:</span> det = <b>ad − bc</b> — el producto de la diagonal que baja, menos el de la diagonal que sube.",
  "matrices-and-vectors.det.formulaSay": "Multiplica la diagonal principal: {a}. Resta la otra diagonal: {b}. {dh} = {d}.",
  "matrices-and-vectors.det.sarrus": "<span class='lead'>La regla de Sarrus</span> (solo 3 × 3): copia las dos primeras columnas a la derecha de la matriz.",
  "matrices-and-vectors.det.copySay": "Escribe otra vez las columnas 1 y 2 a la derecha.",
  "matrices-and-vectors.det.down": "<span class='lead'>Las tres diagonales que bajan</span> (de arriba a la izquierda a abajo a la derecha): multiplica a lo largo de cada una y <b>suma</b>.",
  "matrices-and-vectors.det.downSay": "Diagonales que bajan: {e} = {v}.",
  "matrices-and-vectors.det.up": "<span class='lead'>Las tres diagonales que suben</span> (de abajo a la izquierda a arriba a la derecha): multiplica a lo largo de cada una, súmalas y <b>resta</b> ese total.",
  "matrices-and-vectors.det.upSay": "Diagonales que suben: {e} = {v}.",
  "matrices-and-vectors.det.downMinusUp": "<span class='lead'>Las que bajan menos las que suben:</span>",
  "matrices-and-vectors.det.downMinusUpSay": "Total de las que bajan menos total de las que suben: {d}.",
  "matrices-and-vectors.det.expand": "<span class='lead'>Desarrolla por la fila {r}</span>. Cada entrada se multiplica por su <b>cofactor</b>: el signo del patrón de tablero de ajedrez por el determinante del <b>menor</b> (lo que queda al tachar la fila y la columna de esa entrada).",
  "matrices-and-vectors.det.expandZeros": "<span class='lead'>Desarrolla por la fila {r}</span> — es la que tiene más ceros, y una entrada 0 significa un menor menos que calcular. Cada entrada se multiplica por su <b>cofactor</b>: el signo del patrón de tablero de ajedrez por el determinante del <b>menor</b> (lo que queda al tachar la fila y la columna de esa entrada).",
  "matrices-and-vectors.det.signsSay": "Desarrolla por la fila {r}. Los signos van {s} a lo largo de ella.",
  "matrices-and-vectors.det.entry": "<span class='lead'>Entrada {a}</span> (fila {r}, columna {c}): su signo es <b>{s}</b>. Tacha la fila {r} y la columna {c} para obtener el menor.",
  "matrices-and-vectors.det.minorEq": "menor = {e}",
  "matrices-and-vectors.det.entrySay": "Entrada {a}, signo {s}, menor {m}: {e}.",
  "matrices-and-vectors.det.addTerms": "<span class='lead'>Suma los términos:</span>",
  "matrices-and-vectors.det.skipped1": " (la columna {list} tenía un 0, y 0 por cualquier número es 0.)",
  "matrices-and-vectors.det.skippedN": " (las columnas {list} tenían un 0, y 0 por cualquier número es 0.)",
  "matrices-and-vectors.det.addSay": "Suma los términos: {e} = {d}.",

