  "matrices-and-vectors.det.triangle": "<span class='lead'>Reduce las filas hasta tener un triángulo.</span> Solo se usan dos tipos de operación de filas, y cada una tiene un efecto conocido: <b>sumar un múltiplo de una fila a otra</b> no cambia el determinante, e <b>intercambiar dos filas</b> le cambia el signo. (Multiplicar una fila por k multiplicaría det por k, así que se evita.)",
  "matrices-and-vectors.det.triangleSay": "Usa operaciones de filas para obtener ceros debajo de la diagonal, llevando la cuenta de los intercambios.",
  "matrices-and-vectors.det.noPivot": "<span class='lead'>Una columna sin pivote</span> significa un 0 en la diagonal del triángulo, así que el producto de la diagonal — y el determinante — es <b>0</b>.",
  "matrices-and-vectors.det.noPivotSay": "Si falta un pivote, det es <b>0</b>.",
  "matrices-and-vectors.det.diagSwaps": "<span class='lead'>Multiplica la diagonal</span> del triángulo, y cambia el signo una vez por cada intercambio ({s}).",
  "matrices-and-vectors.det.diagNoSwaps": "<span class='lead'>Multiplica la diagonal</span> del triángulo (sin intercambios, así que el signo no cambia).",
  "matrices-and-vectors.det.diagSay": "Producto de la diagonal: {e} = {d}.",
  "matrices-and-vectors.det.diagSaySwaps": "Producto de la diagonal: {e}, por {s} por los intercambios = {d}.",
  "matrices-and-vectors.det.w.areas": "las áreas",
  "matrices-and-vectors.det.w.volumes": "los volúmenes",
  "matrices-and-vectors.det.w.space": "el espacio",
  "matrices-and-vectors.det.w.sizes": "los tamaños",
  "matrices-and-vectors.det.meanZero": "<span class='lead'>Qué significa det = 0:</span> {a} es <b>singular</b>. No tiene inversa, sus filas (y columnas) son linealmente dependientes — una es combinación de las otras — y un sistema {a}x = b no tiene solución o tiene infinitas, nunca exactamente una. Geométricamente aplasta {w} hasta 0.",
  "matrices-and-vectors.det.mean": "<span class='lead'>Qué significa:</span> det ≠ 0, así que {a} es <b>invertible</b> y todo sistema {a}x = b tiene exactamente una solución. Como transformación, multiplica {w} por |det| = {d}.",
  "matrices-and-vectors.det.meanNeg": "<span class='lead'>Qué significa:</span> det ≠ 0, así que {a} es <b>invertible</b> y todo sistema {a}x = b tiene exactamente una solución. Como transformación, multiplica {w} por |det| = {d}, y el signo menos significa que invierte la orientación (una imagen de espejo).",
  "matrices-and-vectors.det.meanZeroSay": "det = 0: no hay inversa, ni una solución única para un sistema.",
  "matrices-and-vectors.det.meanSay": "det ≠ 0: hay inversa, y los sistemas tienen una solución.",
  "matrices-and-vectors.det.factSingular": "<strong>Singular</strong> — no tiene inversa.",
  "matrices-and-vectors.det.factInvertible": "<strong>Invertible</strong> — tiene inversa (<a href=\"#\" data-goto=\"inv\">hállala</a>).",
  "matrices-and-vectors.det.factMethod": "Método: {m}.",
  "matrices-and-vectors.det.m.sarrus": "regla de Sarrus",
  "matrices-and-vectors.det.m.cofactor": "desarrollo por cofactores",
  "matrices-and-vectors.det.m.rows": "reducción de filas",
